//! Traditional -> Simplified Chinese, character by character.
//!
//! The table (`ts_chars.txt`) is the first candidate of every line of OpenCC's
//! `data/dictionary/TSCharacters.txt` (https://github.com/BYVoid/OpenCC, Apache License 2.0),
//! generated by `scripts/gen_ts_table.py`. Character-level conversion is enough for the short
//! dialogue lines of the game's Traditional Chinese (Taiwan) text.

use std::sync::OnceLock;

static TABLE: &str = include_str!("ts_chars.txt");

/// (traditional, simplified), sorted by the traditional character.
fn pairs() -> &'static [(char, char)] {
    static PAIRS: OnceLock<Vec<(char, char)>> = OnceLock::new();
    PAIRS.get_or_init(|| {
        let mut out: Vec<(char, char)> = TABLE
            .lines()
            .filter(|l| !l.starts_with('#'))
            .filter_map(|l| {
                let mut c = l.chars();
                Some((c.next()?, c.next()?))
            })
            .collect();
        out.sort_unstable_by_key(|p| p.0);
        out
    })
}

pub fn to_simplified(text: &str) -> String {
    let table = pairs();
    text.chars()
        .map(|c| if (c as u32) < 0x2E80 { c } else { table.binary_search_by_key(&c, |p| p.0).map(|i| table[i].1).unwrap_or(c) })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn traditional_lines_become_simplified() {
        assert!(pairs().len() > 3000);
        assert_eq!(to_simplified("老師，過來這邊。\n要和我一起坐嗎？"), "老师，过来这边。\n要和我一起坐吗？");
        assert_eq!(to_simplified("（只能更加努力了。\n不能坐視這座城鎮消失…）"), "（只能更加努力了。\n不能坐视这座城镇消失…）");
        assert_eq!(to_simplified("就，就算被這樣摸…\n也沒有什麼困擾的…"), "就，就算被这样摸…\n也没有什么困扰的…");
        assert_eq!(to_simplified("「開始拍攝──」 Sensei 123"), "「开始拍摄──」 Sensei 123");
        // Already simplified text and kana stay as they are.
        assert_eq!(to_simplified("老师，こっちに来て。"), "老师，こっちに来て。");
    }
}
